  // across an alt-tab must not still be held when the player comes back.
  function releaseAll() {
    keys.clear();
    pressed.clear();
    state.firing = false;
    state.aiming = false;
  }

  function onMouseMove(event) {
    if (!state.locked) return;
    state.lookX += event.movementX;
    state.lookY += event.movementY;
  }

