    const model = new THREE.Group();
    for (const [w, h, d, x, y, z, mat] of MODEL_PARTS[id]) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mats[mat]);
      mesh.position.set(x, y, z);
      model.add(mesh);
