  function alert(bot, x, z) {
    if (!bot.alive) return;
    if (!bot.target) bot.investigate = { x, z };
  }

  return {
    list,
    hitMeshes,
    resetRound,
    update,
    damage,
    alert,
    aliveCount,
  };
}

